WITH events AS (SELECT b.mktcode,b.tgtcode,b.bizdate,b.lastPx/10000.0>b.pressure/10000.0 AND LAG(b.lastPx/10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate)<=LAG(b.pressure/10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS crossed_up,b.lastPx/10000.0<b.pressure/10000.0 AND LAG(b.lastPx/10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate)>=LAG(b.pressure/10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS crossed_down FROM `newzl`.`hsj_stock_hq_basic` b), qualified AS (SELECT mktcode,tgtcode FROM events GROUP BY mktcode,tgtcode HAVING SUM(CASE WHEN crossed_up OR crossed_down THEN 1 ELSE 0 END)>0) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14' AND ABS(b.lastPx/10000.0-b.support/10000.0)/NULLIF(ABS(b.support/10000.0),0)<=0.02 AND b.lastPx/10000.0>=(b.support/10000.0)*0.995;
